package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** One patron a person on a sheet has named: another person on the same sheet, named at most once. */
@Entity
@Table(name = "person_patron")
public class PersonPatron {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "patron_id", nullable = false)
    private Long patronId;

    protected PersonPatron() {}

    public PersonPatron(String sheetId, Long personId, Long patronId) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.patronId = patronId;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public Long getPersonId() { return personId; }

    public Long getPatronId() { return patronId; }

    /** Name another person as the patron in place of the one named. */
    public void setPatronId(Long patronId) { this.patronId = patronId; }
}
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PersonPatronRepository extends JpaRepository<PersonPatron, Long> {

    List<PersonPatron> findBySheetIdOrderByIdAsc(String sheetId);

    List<PersonPatron> findByPersonIdOrderByIdAsc(Long personId);

    boolean existsByPersonIdAndPatronId(Long personId, Long patronId);
}
-- A person's patrons: other people on the same sheet they have named, each at most once.
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CONSTRAINT person_patron_not_self CHECK (person_id <> patron_id)
);
CREATE UNIQUE INDEX person_patron_unique ON person_patron (person_id, patron_id);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, person_id);
