export const NA = 'n/a';

/** Cents times a percent (two decimals), divided by 100, rounded half to even (or half up) to whole cents. */
export function dueCents(amountCents: number, pct: string, halfUp = false): number {
  const [whole, frac = ''] = pct.split('.');
  const pctHundredths = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  // Rounded on the size of the product, so a negative due rounds as its positive would.
  const sign = amountCents < 0 ? -1 : 1;
  const product = BigInt(Math.abs(amountCents)) * pctHundredths;
  const quotient = product / 10000n;
  const remainder = product % 10000n;
  const up = remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n));
  return sign * Number(up ? quotient + 1n : quotient);
}

/** Of one grade's rates, the percent in force on a date (the latest from-date on or before it, unless the
 *  date is after that rate's to-date), or null. */
}

/** A share at most two decimals, more than 0.00 and at most 100.00. */
const SHARE = /^\d{1,3}(\.\d{1,2})?$/;

/** A percent of two decimals in hundredths. */
function hundredths(value: string): number {
  const [whole, frac = ''] = value.split('.');
  return Number(whole) * 100 + Number(frac.padEnd(2, '0'));
}

function percent(hundredths: number): string {
  return `${Math.floor(hundredths / 100)}.${String(hundredths % 100).padStart(2, '0')}`;
}

// The sheet's pools, each name once, and their members: people of the sheet, each at most once in a
// pool, with a share percent. A person can be in several pools. A pool shows its total share and is
// balanced when the shares total exactly 100.00; a retired member's share counts as 0.00 toward it. Each member of a
// balanced pool shows their cut of the sheet's pot (worked out by the server); an unbalanced pool, or no pot, shows none.
export function cents(amount: string): number {
  const negative = amount.startsWith('-');
  const [whole, frac = ''] = (negative ? amount.slice(1) : amount).split('.');
  const size = Number(whole) * 100 + Number(frac.padEnd(2, '0'));
  return negative ? -size : size;
}

/** A correction: a claim with a negative amount. Its due has no floor and no late charge. */
export function money(cents: number): string {
  const size = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(size / 100)}.${String(size % 100).padStart(2, '0')}`;
}

/** What each action makes of a claim, for why it was refused. */
/** Why a void without a reason from the sheet's list is refused. */
const VOID_REASON_NEEDED = 'Choose a reason from the sheet\'s void reasons to void the claim.';

const PAST: Record<ClaimAction, string> = {
  open: 'opened', settle: 'settled', void: 'voided', approve: 'approved', reject: 'rejected',
  resettle: 're-settled',
};

